package com.lianxibu.site.domain.protocol;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.charset.StandardCharsets;import java.time.Instant;import org.junit.jupiter.api.Test;
class CollectorHeartbeatTelemetryTest {
 String wire="{\"observed_at\":\"2026-01-01T00:10:00.000000Z\",\"pending_observations\":0,\"pending_controls\":0,\"quarantined\":2,\"outbox_bytes\":123456,\"free_bytes\":9007199254740991,\"oldest_pending_at\":null}";
 byte[] raw(String value){return value.getBytes(StandardCharsets.UTF_8);}
 @Test void originalSevenFieldsHaveStableCanonicalHashAndNoAdditionalWireMembers(){var value=CollectorHeartbeatTelemetry.parse(raw(wire));assertEquals(7,CanonicalJson.parse(value.canonical()).size());assertEquals(123456,value.sample().outboxBytes());assertEquals(CanonicalJson.MAX_SAFE_INTEGER,value.sample().freeBytes());assertNull(value.sample().oldestPendingAt());assertEquals(value,CollectorHeartbeatTelemetry.parse(raw(value.canonical())));assertEquals(value,CollectorHeartbeatTelemetry.parse(raw("  "+wire+"  ")));assertEquals("CollectorHeartbeatParsed[redacted]",value.toString());assertEquals("CollectorHeartbeatSample[redacted]",value.sample().toString());}
 @Test void realPendingCountsRequireActualNonFutureOldestTimestamp(){var pending=wire.replace("\"pending_controls\":0","\"pending_controls\":1").replace("\"oldest_pending_at\":null","\"oldest_pending_at\":\"2026-01-01T00:09:00.000000Z\"");assertEquals(Instant.parse("2026-01-01T00:09:00Z"),CollectorHeartbeatTelemetry.parse(raw(pending)).sample().oldestPendingAt());assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("\"pending_observations\":0","\"pending_observations\":1"))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(pending.replace("00:09:00","00:10:01"))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(pending.replace("\"pending_controls\":1","\"pending_controls\":0"))));}
 @Test void missingUnknownAndDuplicateFieldsCannotBecomeHealthyZero(){assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("\"quarantined\":2,",""))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("{","{\"rss_bytes\":0,"))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("{","{\"quarantined\":2,"))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("\"outbox_bytes\":123456","\"outbox_bytes\":null"))));}
 @Test void exactIntegersPrecisionAndRawCapacityAreMandatory(){for(String invalid:new String[]{"-1","1.0","\"1\"","9007199254740992"})assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("\"outbox_bytes\":123456","\"outbox_bytes\":"+invalid))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire.replace("00:10:00.000000Z","00:10:00Z"))));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(new byte[4097]));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(null));assertThrows(IllegalArgumentException.class,()->CollectorHeartbeatTelemetry.parse(new byte[0]));}
 @Test void directConstructionCannotBypassNativeTimeAndQueueInvariants(){var at=Instant.parse("2026-01-01T00:10:00Z");assertThrows(IllegalArgumentException.class,()->new CollectorHeartbeatTelemetry.Sample(at,0,1,0,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorHeartbeatTelemetry.Sample(at,0,0,0,0,0,at));assertThrows(IllegalArgumentException.class,()->new CollectorHeartbeatTelemetry.Sample(at.plusNanos(1),0,0,0,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorHeartbeatTelemetry.Sample(at,-1,0,0,0,0,null));}
}
